<template><div class="page-wrap pb-28 lg:pb-8"><NuxtLink to="/customers" class="text-sm font-bold text-slate-500">← Клиенты</NuxtLink><h1 class="mt-5 text-3xl font-black">{{ name }}</h1><p class="mt-2 text-slate-500">Карточка клиента и связанные заявки.</p><div class="mt-6 space-y-3"><RequestCard v-for="request in requests" :key="request.id" :request="request" /></div></div></template>
<script setup lang="ts">import { mockRequests } from '~/data/requests'; const name = decodeURIComponent(useRoute().params.id as string); const requests = mockRequests.filter(item => item.customerCompany === name); if (!requests.length) throw createError({ statusCode: 404, statusMessage: 'Клиент не найден' }); useSeoMeta({ title: name })</script>
